import {modules} from './course.js';
import {$,$$,esc,store,icon} from './ui.js';
import {scene,lessonExperiment,concept} from './scene.js';
import {mountLab,destroyLab,redrawLab} from './lab.js';
const lessons=modules.flatMap((m,mi)=>m.lessons.map((l,i)=>({...l,module:m,moduleIndex:mi,index:i}))),byId=Object.fromEntries(lessons.map(l=>[l.id,l]));
const state={lesson:lessons[0],step:0,mode:'learn',open:new Set([modules[0].id]),done:new Set(store.get('done',[]).filter(id=>byId[id])),solved:new Set(store.get('solved',[]).filter(id=>byId[id])),paused:false,conceptView:false,searchIndex:0,filter:'all',choice:null,checked:false,labType:'ownership'};
const logo='<img class="rust-logo" src="./assets/favicon.svg" alt="">',totalSteps=lessons.reduce((n,l)=>n+l.steps.length,0);
function highlight(code){return esc(code).replace(/\b(fn|let|mut|pub|use|mod|impl|trait|struct|enum|match|if|else|for|in|loop|while|return|move|async|await|unsafe|where|const|static|Self|self|Some|None|Ok|Err)\b/g,'<span class="kw">$1</span>')}
function prose(s){return esc(s).replace(/`([^`]+)`/g,'<code>$1</code>')}
$('#app').innerHTML=`<div class="app-window"><header class="topbar"><button class="icon-btn menu-button" data-action="drawer" aria-label="Open the course menu">${icon('menu')}</button><a class="brand" href="#/rust-journey/1">${logo}<span>Rust <mark>School</mark></span></a><nav class="main-nav" aria-label="Main navigation">${[['learn','book','Learn'],['practice','spark','Practice'],['lab','terminal','Rust Lab'],['cheatsheets','grid','Cheatsheets']].map(([mode,i,name])=>`<button class="nav-btn ${mode==='learn'?'active':''}" data-mode="${mode}">${icon(i)}<span>${name}</span></button>`).join('')}</nav><div class="header-right"><button class="search-trigger" data-action="search" aria-label="Search the course">${icon('search')}<span>Search lessons & concepts…</span><kbd>Ctrl K</kbd></button><button class="icon-btn" id="theme" data-action="theme" aria-label="Switch to dark theme">${icon('moon')}</button><div class="header-note">from hello to production.<br><strong>one idea at a time.</strong></div></div></header><div class="body-grid"><aside class="sidebar" aria-label="Course"><button class="icon-btn drawer-close" data-action="close-drawer" aria-label="Close the course menu">${icon('x')}</button><div class="course-heading"><span>${icon('book')} Course</span><small>72 lessons</small></div><div class="course-scroll" id="course"></div><div id="progress"></div><div class="sidebar-foot">${icon('database')} Your progress stays on this device</div></aside><main class="workspace" id="workspace"></main></div><button class="drawer-backdrop" data-action="close-drawer" aria-label="Close the course menu"></button></div>`;
function renderSidebar(){ $('#course').innerHTML=modules.map((m,mi)=>`<section class="module ${state.open.has(m.id)?'open':''}"><button class="module-toggle" data-module="${m.id}" aria-expanded="${state.open.has(m.id)}">${icon('chevron','chevron')}<span class="folder" style="background:${m.color}"></span><span>${String(mi+1).padStart(2,'0')}. ${esc(m.title)}</span><span class="module-count">${m.lessons.filter(l=>state.done.has(l.id)).length}/${m.lessons.length}</span></button><ul class="lesson-list">${m.lessons.map(l=>`<li><a class="lesson-link ${state.mode==='learn'&&state.lesson.id===l.id?'active':''}" href="#/${l.id}/1" ${state.mode==='learn'&&state.lesson.id===l.id?'aria-current="page"':''}>${icon(state.done.has(l.id)?'check':'file',state.done.has(l.id)?'done':'')}<span>${esc(l.short)}</span></a></li>`).join('')}</ul></section>`).join('');$('#progress').innerHTML=`<div class="progress-card"><div class="progress-top"><span>Progress</span><strong>${state.done.size} / 72</strong></div><div class="progress-track" role="progressbar" aria-label="Course completion" aria-valuemin="0" aria-valuemax="72" aria-valuenow="${state.done.size}"><span style="width:${state.done.size/72*100}%"></span></div></div>`;}
function renderTheme(){const dark=document.documentElement.dataset.theme==='dark';$('#theme').innerHTML=icon(dark?'sun':'moon');$('#theme').setAttribute('aria-label',dark?'Switch to light theme':'Switch to dark theme')}
function setRoute(id,step=0){location.hash=`#/${id}/${step+1}`}
function route(){const parts=location.hash.replace(/^#\/?/,'').split('/');destroyLab();state.conceptView=false;state.choice=null;state.checked=false;document.body.classList.remove('drawer-open');const old=state.lesson.id;state.labType=parts[1]||'ownership';if(['lab','practice','cheatsheets'].includes(parts[0])){state.mode=parts[0];state.challenge=parts[0]==='practice'&&byId[parts[1]]?byId[parts[1]]:null}else{state.mode='learn';let last=store.get('last',{});state.lesson=byId[parts[0]]||byId[last.id]||lessons[0];state.step=Math.max(0,Math.min(state.lesson.steps.length-1,parts[0]&&byId[parts[0]]?Number(parts[1]||1)-1:Number(last.step)||0));if(!Number.isFinite(state.step))state.step=0;if(old!==state.lesson.id||!state.open.has(state.lesson.module.id))state.open.add(state.lesson.module.id);store.set('last',{id:state.lesson.id,step:state.step});if(state.step===state.lesson.steps.length-1){state.done.add(state.lesson.id);store.set('done',[...state.done])}}render();}
function render(){renderSidebar();$$('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===state.mode));$('#workspace').className=state.mode==='learn'?'workspace':'workspace wide-workspace';if(state.mode==='learn')renderLesson();else if(state.mode==='lab')mountLab($('#workspace'),state.labType);else if(state.challenge)renderQuiz();else if(state.mode==='practice')renderPractice();else renderCheats();document.title=`${state.mode==='learn'?state.lesson.title:state.mode==='lab'?'Rust Lab':state.mode==='practice'?'Practice':'Cheatsheets'} · Rust School`;}

let searchResults=[],searchReturnFocus=null;
function openSearch(){if($('.modal-backdrop'))return;searchReturnFocus=document.activeElement;const modal=document.createElement('div');modal.className='modal-backdrop';modal.innerHTML=`<section class="search-dialog" role="dialog" aria-modal="true" aria-label="Search the course"><div class="search-input-row">${icon('search')}<input id="search-input" role="combobox" aria-controls="search-results" aria-expanded="true" aria-autocomplete="list" aria-label="Search lessons and Rust concepts" placeholder="Search lessons, keywords, concepts…"><button data-action="close-search" aria-label="Close search">esc</button></div><div class="search-results" id="search-results" role="listbox" aria-label="Search results"></div><div class="search-footer"><span>↑ ↓ move · Enter open · esc close</span><span>72 lessons · ${totalSteps} steps</span></div></section>`;document.body.append(modal);modal.addEventListener('click',e=>{if(e.target===modal)closeSearch()});$('#search-input').addEventListener('input',()=>renderSearch());renderSearch();$('#search-input').focus();}
function closeSearch(){$('.modal-backdrop')?.remove();searchReturnFocus?.focus()}
function renderSearch(){const q=$('#search-input').value.toLowerCase().trim();searchResults=lessons.filter(l=>(l.title+' '+l.summary+' '+l.steps.map(s=>s.code).join(' ')+' '+l.goals.join(' ')).toLowerCase().includes(q));state.searchIndex=0;$('#search-results').innerHTML=searchResults.length?searchResults.map((l,i)=>`<button id="search-option-${i}" role="option" aria-selected="${i===0}" class="search-option ${i===0?'selected':''}" data-search-id="${l.id}">${icon('file')}<span><strong>${esc(l.title)}</strong><small>${esc(l.summary)}</small></span></button>`).join(''):'<div class="empty-state">No matching lessons. Try “ownership”, “trait”, or “async”.</div>';$('#search-input').setAttribute('aria-activedescendant',searchResults.length?'search-option-0':'')}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}

document.addEventListener('keydown',e=>{const edit=e.target.closest('input,textarea,[contenteditable]');if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('.modal-backdrop')?closeSearch():openSearch();return}if($('.modal-backdrop')){if(e.key==='Escape'){closeSearch();return}if(e.key==='Tab'){const controls=[$('#search-input'),$('.search-input-row button'),...$$('.search-option')];const at=controls.indexOf(document.activeElement);if(e.shiftKey&&at===0){e.preventDefault();controls.at(-1).focus()}else if(!e.shiftKey&&at===controls.length-1){e.preventDefault();controls[0].focus()}return}if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();state.searchIndex=Math.max(0,Math.min(searchResults.length-1,state.searchIndex+(e.key==='ArrowDown'?1:-1)));$$('.search-option').forEach((b,i)=>{b.classList.toggle('selected',i===state.searchIndex);b.setAttribute('aria-selected',String(i===state.searchIndex))});$('#search-input').setAttribute('aria-activedescendant','search-option-'+state.searchIndex);$('#search-option-'+state.searchIndex)?.scrollIntoView({block:'nearest'});}if(e.key==='Enter'&&edit&&searchResults[state.searchIndex]){e.preventDefault();const id=searchResults[state.searchIndex].id;closeSearch();setRoute(id)}return}if(e.key==='Escape'){document.body.classList.remove('drawer-open');return}if(edit||e.ctrlKey||e.metaKey||e.altKey||state.mode!=='learn')return;if(e.key==='ArrowRight'){e.preventDefault();next()}if(e.key==='ArrowLeft'&&state.step>0){e.preventDefault();setRoute(state.lesson.id,state.step-1)}if(e.key.toLowerCase()==='r')$('[data-action="replay"]')?.click();if(e.code==='Space'){e.preventDefault();$('#pause-button')?.click()}});

function metric(label,value,i){return `<div class="metric"><div class="metric-label">${icon(i)} ${label}</div><div class="metric-value">${value}</div></div>`}
function renderLesson(){const l=state.lesson,s=l.steps[state.step],last=state.step===l.steps.length-1,nextLesson=lessons[lessons.findIndex(x=>x.id===l.id)+1];state.experiment=lessonExperiment(l,s);const x=state.experiment;$('#workspace').innerHTML=`<section class="sheet fade-in"><div class="crumb"><b>${String(l.moduleIndex+1).padStart(2,'0')}. ${esc(l.module.title)}</b> / Lesson ${l.index+1} of ${l.module.lessons.length}</div><div class="lesson-title-row"><h1>${esc(l.title)}</h1><div class="tags"><span class="tag sand">${icon('clock')}${l.minutes} min</span><span class="tag green">${icon('signal')}${esc(l.level)}</span><span class="tag violet">${icon('list')}${l.steps.length} steps</span></div></div><p class="subtitle">${esc(l.summary)}</p><div class="stage ${state.paused?'paused':''}" id="stage"><div class="stage-hud">${metric('Edition','2024','code')}${metric('Focus',x.focus,'database')}${metric('Stage',x.stage,'bolt')}<div class="stage-tools"><button class="tool" data-action="replay" title="Replay this step (R)">${icon('replay')}<span>Replay</span></button><button class="tool" data-action="pause" id="pause-button" title="Pause animation (Space)">${icon(state.paused?'play':'pause')}<span>${state.paused?'Play':'Pause'}</span></button></div></div><div class="stage-viewport" id="stage-viewport">${scene(l,s,x)}</div><div class="stage-legend"><span><i class="legend-dot orange"></i>your code</span><span><i class="legend-dot purple"></i>the checks</span><span><i class="legend-dot green"></i>the result</span><button class="run-small" style="margin-left:auto" data-action="toggle-view" id="view-toggle">Show insight</button></div><div class="query-dock"><div class="dock-head"><span>${icon('code')} main.rs</span><button class="run-small" data-action="try-model">${icon('play')} Try in Rust Lab</button></div><pre class="query-code rust-code">${highlight(s.code)}</pre><div class="notebook-caption">Illustrative Rust · follow the idea, one step at a time</div></div></div><section class="timeline"><div class="timeline-head">In this lesson<span>Step ${state.step+1} of ${l.steps.length}</span></div><div class="timeline-steps">${l.steps.map((st,i)=>`<button class="step-button ${i===state.step?'active':i<state.step?'visited':''}" data-step="${i}" aria-label="Step ${i+1}: ${esc(st.label)}" ${i===state.step?'aria-current="step"':''}><span class="step-number">${i+1}</span><span class="step-label">${esc(st.label)}</span></button>`).join('')}</div></section></section><aside class="rail"><section class="guide fade-in"><div class="guide-head"><span>Step ${state.step+1} / ${l.steps.length}</span><span class="phase-pill ${s.phase}">${s.phase==='recap'?'Recap':state.step===0?'Problem':'Technique'}</span></div><div class="guide-content"><h2>${esc(s.title)}</h2><p>${prose(s.body)}</p><div class="callout">${icon('spark')}<div><h3>${last?'Remember this':'Key idea'}</h3><p>${prose(s.callout)}</p></div></div>${last?`<button class="btn" data-practice="${l.id}">${icon('spark')} Check your understanding</button>`:''}</div><div class="guide-nav"><button class="btn back" data-action="back" ${state.step===0?'disabled':''}>Back</button><button class="btn primary next" data-action="next">${last?(nextLesson?'Next lesson':'Finish course'):'Next: '+esc(l.steps[state.step+1].label)}</button></div><div class="shortcuts"><kbd>←</kbd><kbd>→</kbd> step · <kbd>R</kbd> replay · <kbd>Space</kbd> pause</div></section><section class="goals ${state.done.has(l.id)?'complete':''}"><h3>You’ll learn</h3><ul>${l.goals.map(g=>`<li><span class="check-box"></span><span>${esc(g)}</span></li>`).join('')}</ul></section><div class="rail-note"><a href="${esc(l.source||'https://doc.rust-lang.org/book/')}" target="_blank" rel="noopener noreferrer">${icon('book')} Read the official documentation</a></div></aside>`;applyPaused();}
function updateStageView(){if(!$('#stage-viewport'))return;$('#view-toggle').textContent=state.conceptView?'Show diagram':'Show insight';$('#stage-viewport').innerHTML=state.conceptView?concept(state.lesson,state.lesson.steps[state.step],state.experiment):scene(state.lesson,state.lesson.steps[state.step],state.experiment);applyPaused()}
function applyPaused(){const svg=$('.diagram');if(svg){if(state.paused||matchMedia('(prefers-reduced-motion: reduce)').matches)svg.pauseAnimations?.();else svg.unpauseAnimations?.()}$('#stage')?.classList.toggle('paused',state.paused)}
function next(){if(state.step<state.lesson.steps.length-1)setRoute(state.lesson.id,state.step+1);else{const l=lessons[lessons.findIndex(l=>l.id===state.lesson.id)+1];if(l)setRoute(l.id);else{toast('You reached the end. Put your understanding to work in Practice.');location.hash='#/practice'}}}
function pageHeading(kicker,title,description,action=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${description}</p></div>${action}</div>`}
function renderPractice(){const selected=state.filter==='all'?lessons:lessons.filter(l=>l.module.id===state.filter);$('#workspace').innerHTML=pageHeading('LESS MEMORIZING. MORE REASONING.','Turn an idea into understanding.',`${state.solved.size} of ${lessons.length} solved. Real decisions from the Rust workflow.`)+`<div class="filter-chips"><button class="filter-chip ${state.filter==='all'?'active':''}" data-filter="all">All challenges</button>${modules.map(m=>`<button class="filter-chip ${state.filter===m.id?'active':''}" data-filter="${m.id}">${esc(m.title)}</button>`).join('')}</div><div class="practice-grid">${selected.map(l=>`<article class="practice-card"><span class="card-index">${esc(l.module.title)} · ${esc(l.level)}</span><h2>${esc(l.title)}</h2><p>${esc(l.quiz.question)}</p><button class="btn ${state.solved.has(l.id)?'':'primary'}" data-practice="${l.id}">${icon(state.solved.has(l.id)?'check':'spark')}${state.solved.has(l.id)?'Solved · try again':'Take the challenge'}</button></article>`).join('')}</div>`;}
function renderQuiz(){const l=state.challenge,q=l.quiz,correct=state.checked&&state.choice===q.answer;$('#workspace').innerHTML=pageHeading('PRACTICE / '+esc(l.module.title),esc(l.title),'Think it through. Choose an answer. Learn why it works.','<button class="btn" data-mode="practice">All challenges</button>')+`<div class="quiz-layout"><section class="quiz-card"><div class="eyebrow">A MOMENT TO THINK</div><h2>${esc(q.question)}</h2><div class="quiz-options" role="group" aria-label="Answer choices">${q.options.map((o,i)=>`<button class="quiz-option ${state.choice===i?'selected':''} ${state.checked&&i===q.answer?'correct':state.checked&&state.choice===i?'incorrect':''}" data-choice="${i}" aria-pressed="${state.choice===i}"><span class="letter">${'ABCD'[i]}</span><span>${esc(o)}</span></button>`).join('')}</div><div aria-live="polite">${state.checked?`<div class="quiz-feedback ${correct?'success':''}"><strong>${correct?'✓ You’ve got it.':'A useful distinction.'}</strong>${esc(q.explanation)}</div>`:''}</div><div class="quiz-actions"><a class="btn" href="#/${l.id}/1">${icon('book')} Review lesson</a><button class="btn primary" data-action="${correct?'next-quiz':'check-quiz'}" ${state.choice===null?'disabled':''}>${correct?'Next challenge →':'Check answer'}</button></div></section><p class="quiz-foot">${icon('clock')} Take your time. Your progress is saved on this device.</p></div>`;}
const cheats=[
 ['A Cargo workflow','Create, check, test, and build. Keep Cargo.lock for reproducible application dependency resolution.','cargo new hello_rust\ncd hello_rust\ncargo check\ncargo test\ncargo run\ncargo build --release'],
 ['Move, borrow, or clone','Passing an owned String transfers ownership. Borrow for temporary access; clone when a separate owned copy is intentional.','let message = String::from("hello");\nlet borrowed = &message;\nprintln!("{borrowed}");\nlet separate = message.clone();\nlet moved = message;'],
 ['One exclusive reference','A mutable borrow provides exclusive access while it is in use. A later borrow is allowed once the earlier use has ended.','let mut text = String::from("Rust");\nlet view = &text;\nprintln!("{view}");\nlet edit = &mut text;\nedit.push_str(" is fun");'],
 ['Make absence explicit','Option represents something that may be missing. Handle both cases or supply a meaningful default.','let items = [3, 5, 8];\nmatch items.get(9) {\n    Some(value) => println!("{value}"),\n    None => println!("No item at that index"),\n}'],
 ['Propagate a recoverable error','The question-mark operator returns early on Err and unwraps Ok. The containing function needs a compatible return type.','fn read_count(path: &str) -> Result<usize, std::io::Error> {\n    let text = std::fs::read_to_string(path)?;\n    Ok(text.lines().count())\n}'],
 ['Describe behavior with traits','Trait bounds specify required behavior without committing to one concrete implementation.','fn show<T: std::fmt::Display>(value: T) {\n    println!("{value}");\n}\nshow(42);\nshow("hello");'],
 ['Relate borrowed lifetimes','An annotation describes a relationship; it does not keep a value alive longer. Here the output borrows from the input.','fn first_word(text: &str) -> &str {\n    text.split_whitespace().next().unwrap_or("")\n}\nlet message = String::from("hello Rust");\nprintln!("{}", first_word(&message));'],
 ['Build an iterator pipeline','Adapters are lazy. collect, sum, fold, and iteration drive the work. into_iter consumes owned items.','let values = vec![1, 2, 3, 4, 5];\nlet doubled: Vec<i32> = values.into_iter()\n    .filter(|x| x % 2 == 0)\n    .map(|x| x * 2)\n    .collect();'],
 ['Share state deliberately','Arc shares ownership across threads; a Mutex guards access to the inner value. Keep lock scopes small.','use std::sync::{Arc, Mutex};\nlet count = Arc::new(Mutex::new(0));\nlet shared = Arc::clone(&count);\nlet worker = std::thread::spawn(move || {\n    *shared.lock().unwrap() += 1;\n});\nworker.join().unwrap();'],
 ['Test behavior','Assert observable outcomes. Add integration tests for public APIs and document expected failure modes.','fn double(n: i32) -> i32 { n * 2 }\n#[test]\nfn doubles_negative_numbers() {\n    assert_eq!(double(-3), -6);\n}'],
 ['Keep the feedback loop short','Formatting, linting, tests, and documentation are separate checks. Run them in CI against supported toolchains.','cargo fmt --check\ncargo clippy --all-targets -- -D warnings\ncargo test --all-targets\ncargo test --doc\ncargo doc --no-deps'],
 ['Ship with a checklist','A successful build is one part of release readiness. Test configuration, observability, shutdown, and rollback.','// Production review:\n// 1. Validate configuration and secrets.\n// 2. Bound inputs, queues, and concurrency.\n// 3. Add structured logs and health checks.\n// 4. Handle shutdown and in-flight requests.\n// 5. Exercise migration and rollback paths.']
];
function renderCheats(){$('#workspace').innerHTML=pageHeading('A LITTLE HELP, RIGHT WHEN YOU NEED IT.','The Rust field guide.','Patterns for ownership, everyday code, and the journey to production.')+`<div class="cheat-grid">${cheats.map(([title,desc,code],i)=>`<article class="cheat-card"><h2>${icon('code')}${title}</h2><p>${desc}</p><pre>${highlight(code)}</pre><button class="btn" data-copy="${i}">${icon('copy')} Copy pattern</button></article>`).join('')}</div><p class="footnote">Rust and shell patterns are illustrative fragments. Use complete programs from Rust Lab to experiment in <a href="https://play.rust-lang.org/" target="_blank" rel="noopener noreferrer">Rust Playground</a>. Continue with <a href="https://doc.rust-lang.org/book/" target="_blank" rel="noopener noreferrer">The Rust Book</a>.</p>`;}

document.addEventListener('click',async e=>{const b=e.target.closest('button,a');if(!b)return;
 if(b.dataset.module){const id=b.dataset.module;state.open.has(id)?state.open.delete(id):state.open.add(id);renderSidebar();return}
 if(b.dataset.mode){if(b.dataset.mode==='learn')setRoute(state.lesson.id,state.step);else location.hash='#/'+b.dataset.mode;return}
 if(b.dataset.step!==undefined){setRoute(state.lesson.id,Number(b.dataset.step));return}
 if(b.dataset.practice){location.hash='#/practice/'+b.dataset.practice;return}
 if(b.dataset.filter){state.filter=b.dataset.filter;renderPractice();return}
 if(b.dataset.searchId){closeSearch();setRoute(b.dataset.searchId);return}
 if(b.dataset.choice!==undefined){state.choice=Number(b.dataset.choice);state.checked=false;renderQuiz();$('[data-choice="'+state.choice+'"]').focus();return}
 if(b.dataset.copy!==undefined){try{await navigator.clipboard.writeText(cheats[Number(b.dataset.copy)][2]);toast('Pattern copied')}catch{toast('Select the code to copy it manually.')}return}
 switch(b.dataset.action){
 case 'drawer':document.body.classList.add('drawer-open');$('.drawer-close').focus();break;
 case 'close-drawer':document.body.classList.remove('drawer-open');$('.menu-button').focus();break;
 case 'theme':document.documentElement.dataset.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';store.set('theme',document.documentElement.dataset.theme);renderTheme();redrawLab();break;
 case 'search':openSearch();break;case 'close-search':closeSearch();break;
 case 'next':next();break;case 'back':if(state.step>0)setRoute(state.lesson.id,state.step-1);break;
 case 'replay':state.conceptView=false;updateStageView();$('.diagram')?.setCurrentTime?.(0);toast('Replaying this step');break;
 case 'pause':state.paused=!state.paused;$('#pause-button').innerHTML=icon(state.paused?'play':'pause')+`<span>${state.paused?'Play':'Pause'}</span>`;$('#pause-button').title=(state.paused?'Play':'Pause')+' animation (Space)';applyPaused();break;
 case 'toggle-view':state.conceptView=!state.conceptView;updateStageView();break;
 case 'try-model':location.hash='#/lab/'+state.lesson.lab;break;
 case 'check-quiz':if(state.choice===null)break;state.checked=true;if(state.choice===state.challenge.quiz.answer){state.solved.add(state.challenge.id);store.set('solved',[...state.solved])}renderQuiz();break;
 case 'next-quiz':{const i=lessons.findIndex(l=>l.id===state.challenge.id);location.hash=i<lessons.length-1?'#/practice/'+lessons[i+1].id:'#/practice';break;}
 }
});
window.addEventListener('hashchange',route);renderTheme();route();
